private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (bb == null || sb == null) {
        throw new IllegalArgumentException("ByteBuffer and StringBuilder cannot be null");
    }
    if (i < 0 || i >= bb.remaining()) {
        throw new IndexOutOfBoundsException("Index out of bounds");
    }

    while (i < bb.remaining()) {
        byte b = bb.get(i);
        if (b >= 0) {
            sb.append((char) b);
            i++;
        } else {
            int codePoint = 0;
            int numBytes = 0;
            if ((b & 0xE0) == 0xC0) {
                codePoint = (b & 0x1F) << 6;
                numBytes = 1;
            } else if ((b & 0xF0) == 0xE0) {
                codePoint = (b & 0x0F) << 12;
                numBytes = 2;
            } else if ((b & 0xF8) == 0xF0) {
                codePoint = (b & 0x07) << 18;
                numBytes = 3;
            } else {
                // Invalid UTF-8 start byte
                i++;
                continue;
            }

            for (int j = 0; j < numBytes; j++) {
                b = bb.get(++i);
                if ((b & 0xC0) != 0x80) {
                    // Invalid UTF-8 continuation byte
                    i--;
                    break;
                }
                codePoint |= (b & 0x3F) << ((numBytes - j - 1) * 6);
            }

            if (numBytes == 1) {
                // Invalid UTF-8 sequence
                i--;
                continue;
            }

            sb.appendCodePoint(codePoint);
        }
    }

    return i;
}
