static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        // Extract year, month, and day from the time bucket
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        // Adjust the day based on the dayStep
        if (dayStep == 1) {
            // No adjustment needed
        } else if (dayStep == 2) {
            day = (day - 1) / 2 * 2 + 1;
        } else if (dayStep == 3) {
            day = (day - 1) / 3 * 3 + 1;
        } else if (dayStep == 4) {
            day = (day - 1) / 4 * 4 + 1;
        } else if (dayStep == 5) {
            day = (day - 1) / 5 * 5 + 1;
        } else if (dayStep == 6) {
            day = (day - 1) / 6 * 6 + 1;
        } else if (dayStep == 7) {
            day = (day - 1) / 7 * 7 + 1;
        } else if (dayStep == 8) {
            day = (day - 1) / 8 * 8 + 1;
        } else if (dayStep == 9) {
            day = (day - 1) / 9 * 9 + 1;
        } else if (dayStep == 10) {
            day = (day - 1) / 10 * 10 + 1;
        } else if (dayStep == 11) {
            day = (day - 1) / 11 * 11 + 1;
        } else {
            throw new IllegalArgumentException("Invalid dayStep value: " + dayStep);
        }

        // Reconstruct the time bucket with the adjusted day
        return year * 10000 + month * 100 + day;
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid input: " + timeBucket + ", " + dayStep, e);
    }
}
