public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        throw new IllegalArgumentException("Key and properties cannot be null");
    }

    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }

    return performVariableSubstitution(value, props);
}

private static String performVariableSubstitution(String value, Properties props) {
    StringBuilder result = new StringBuilder();
    int startIndex = 0;

    while (startIndex < value.length()) {
        int dollarIndex = value.indexOf('$', startIndex);
        if (dollarIndex == -1) {
            result.append(value.substring(startIndex));
            break;
        }

        result.append(value.substring(startIndex, dollarIndex));

        int endIndex = value.indexOf('}', dollarIndex);
        if (endIndex == -1) {
            result.append(value.substring(dollarIndex));
            break;
        }

        String variableName = value.substring(dollarIndex + 1, endIndex);
        String variableValue = props.getProperty(variableName);
        if (variableValue != null) {
            result.append(variableValue);
        } else {
            result.append(value.substring(dollarIndex, endIndex + 1));
        }

        startIndex = endIndex + 1;
    }

    return result.toString();
}
