private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<Integer,E> graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    for (Edge<E> edge : graph.getEdges()) {
        List<Pair<Integer,Integer>> localSeparatorList = new ArrayList<>();
        int u = edge.getSource();
        int v = edge.getTarget();

        // Get the neighborhood of u and v
        Set<Integer> neighborsU = graph.getNeighbors(u);
        Set<Integer> neighborsV = graph.getNeighbors(v);

        // Find the minimal separators in the neighborhood of the edge
        for (int neighbor : neighborsU) {
            if (neighbor != v && neighborsV.contains(neighbor)) {
                localSeparatorList.add(new Pair<>(neighbor, u));
            }
        }

        // Add the local separator list and the edge to the global separator list
        globalSeparatorList.add(new Pair<>(localSeparatorList, edge));
    }

    return globalSeparatorList;
}
